entries[19669] = { ["name"] = "Arkanitdietrich", ["text"] = "Wirken in 5.125 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren , Verdichteter Schleifstein\nErmöglicht das Öffnen von kniffligen Schlössern. Dieser Vorgang verzehrt den Dietrich.\nArkanitdietrich\n(2)\nBenötigt Schmiedekunst\n(275)\nBenutzen: Ermöglicht das Öffnen von kniffligen Schlössern. Dieser Vorgang verzehrt den Dietrich." }
