entries[19712] = { ["name"] = "Arkane Explosion", ["text"] = "Wirken in 0.5 sek.\nLässt eine Druckwelle aus Magie entstehen und fügt in der Nähe befindlichen Feinden 925 bis 1075 Arkanschaden zu." }
