entries[19715] = { ["name"] = "Gegenzauber", ["text"] = "30 Meter Reichweite\nSofort\nKontert das Zauberwirken von in der Nähe befindlichen Feinden und verhindert 10 Sek. lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung." }
