entries[19740] = { ["name"] = "Segen der Macht", ["text"] = "20 Mana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und erhöht 10 Min. lang die Angriffskraft um 20. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[19742] = { ["name"] = "Segen der Weisheit", ["text"] = "30 Mana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und stellt 10 Min. lang alle 5 Sek. 10 Mana wieder her. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[19746] = { ["name"] = "Aura der Konzentration", ["text"] = "Sofort\nGewährt allen Gruppenmitgliedern im Umkreis von 30 Metern eine Chance von 35%, Zauberunterbrechung bei erlittenem Schaden zu vermeiden. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
