entries[19752] = { ["name"] = "Göttliches Eingreifen", ["text"] = "40 Meter Reichweite\nSofort 1 Stunde Abklingzeit\nReagenzien:\nSymbol der Offenbarung\nOpfert den Paladin, um das ausgewählte Gruppenmitglied aus dem Kampf zu entfernen und es gegen jeglichen Schaden abzuschirmen. Gegner greifen das geschützte Ziel nicht weiter an. Allerdings kann es 3 Min. lang keinerlei Aktionen durchführen." }
