entries[19814] = { ["name"] = "Meisterliche Zielattrappe", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilgehäuse , Thoriumröhre , Thoriumapparat (2), Echtsilberbarren , Unverwüstliches Leder (2), Runenstoff (4)\nBenötigt Ingenieurskunst\n(275)\nBenutzen: Lässt eine Zielattrappe auf den Boden fallen, die in der Nähe befindliche Monster dazu bringt, sie anzugreifen. Die Attrappe bleibt bis zu ihrer Zerstörung aktiv, maximal jedoch für 15 Sekunden. (2 Min Abklingzeit)" }
entries[19815] = { ["name"] = "Empfindlicher Arkanitwandler", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nArkanitbarren , Eisenweberseide" }
entries[19816] = { ["name"] = "Feuerball", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 3 sek.\nFügt einem Gegner Feuerschaden zu." }
entries[19817] = { ["name"] = "Doppelangriff", ["text"] = "Gewährt dem Zaubernden 0 zusätzliche Angriffe.\n(Procchance: 10%, 3s Abklingzeit)" }
