entries[19819] = { ["name"] = "Modularer Stimmenverstärker", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEmpfindlicher Arkanitwandler (2), Goldkraftkern , Thoriumapparat , Großer Opal\nModularer Stimmenverstärker\nWird beim Anlegen gebunden\nHals\nAnlegen: Verringert die Wirkungsdauer jeglicher Stille- und Unterbrechungseffekte gegen den Träger um 10%. Dieser Effekt ist nicht mit anderen Effekten dieser Art stapelbar." }
entries[19820] = { ["name"] = "Zerfleischen", ["text"] = "10 Meter Reichweite\nSofort\nVerursacht alle 2 Sek. 300 Schaden bei einem Feind und verringert sein Bewegungstempo um 50%. Hält 20 Sek. lang an." }
entries[19821] = { ["name"] = "Arkane Bombe", ["text"] = "15 Meter Reichweite\nWirken in 1.5 sek.\nZieht 675 bis 1125 Mana von allen ab, die sich im Umkreis des Schlages befinden und fügt dem Ziel einen Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Schlagbereich außerdem 5 Sek. lang zum Schweigen." }
