entries[19823] = { ["name"] = "Feuernova - Bild" }
entries[19825] = { ["name"] = "Schutzbrille des Meisteringenieurs", ["text"] = "Wirken in 50 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFeuerschutzbrille , Gewaltiger Smaragd (2), Verzaubertes Leder (4)\nSchutzbrille des Meisteringenieurs\nWird beim Anlegen gebunden\nKopf Stoff\n61 Rüstung\n+16 Ausdauer\n+17 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst\n(280)" }
entries[19830] = { ["name"] = "Arkanitdrachling", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMechanischer Mithrildrachling , Empfindlicher Arkanitwandler (8), Verzauberter Thoriumbarren (10), Thoriumapparat (6), Goldkraftkern (4), Verzaubertes Leder (6)\nArkanitdrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n50\nBenötigt Ingenieurskunst\n(300)\nBenutzen: Aktiviert Euren Arkanitdrachling, damit er 1 Min. lang für Euch kämpft. (20 Min Abklingzeit)" }
entries[19831] = { ["name"] = "Arkane Bombe", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nEmpfindlicher Arkanitwandler , Thoriumbarren (3), Runenstoff\n(3)\nBenötigt Ingenieurskunst\n(300)\nBenutzen: Zieht 675 bis 1125 Mana von allen ab, die sich im Umkreis des Schlages befinden und fügt dem Ziel einen Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Schlagbereich außerdem 5 Sek. lang zum Schweigen. (1 Min Abklingzeit)" }
entries[19832] = { ["name"] = "Besitz ergreifen" }
entries[19833] = { ["name"] = "Fehlerloses Arkanitgewehr", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nArkanitbarren (10), Thoriumröhre (2), Essenz des Feuers (2), Essenz der Erde (2), Azerothischer Diamant (2), Verzaubertes Leder (2)\nFehlerloses Arkanitgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n83 - 155 Schaden Tempo 3.00\n(39.67 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n56\nAnlegen: Erhöht die kritische Trefferwertung um 9.\nAnlegen: Erhöht die Distanzangriffskraft um 10." }
