entries[20014] = { ["name"] = "Umhang - Großer Widerstand", ["text"] = "Wirken in 5 sek.\nBenötigt Umhang\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nGeringe ewige Essenz (2), Herz des Feuers , Erdenkern , Kugel des Wassers , Odem des Windes , Sekret des Untodes\nEinen Umhang dauerhaft verzaubern, sodass alle Widerstände um 5 erhöht werden." }
entries[20015] = { ["name"] = "Umhang - Überragende Verteidigung", ["text"] = "Wirken in 5 sek.\nBenötigt Umhang\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nIllusionsstaub (8)\nEinen Umhang dauerhaft verzaubern, sodass die Rüstung zusätzlich um 70 erhöht wird." }
entries[20016] = { ["name"] = "Schild - Erhebliche Willenskraft", ["text"] = "Wirken in 5 sek.\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nGroße ewige Essenz (2), Illusionsstaub (4)\nEinen Schild dauerhaft verzaubern, sodass die Willenskraft um +9 erhöht wird." }
entries[20017] = { ["name"] = "Schild - Große Ausdauer", ["text"] = "Wirken in 5 sek.\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nTraumstaub (10)\nEinen Schild dauerhaft verzaubern, sodass die Ausdauer um +7 erhöht wird." }
entries[20018] = { ["name"] = "Gesundheitsstein herstellen (erheblich)", ["text"] = "Sofort\nLässt einen erheblichen Gesundheitsstein entstehen, der verwendet werden kann, um sofort 1200 Gesundheit wiederherzustellen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[20019] = { ["name"] = "Einhüllende Flammen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSetzt einen Feind in Brand, fügt ihm im Verlauf von 6 Sek. 1500 Feuerschaden zu und versetzt ihn in Panik. Solange das Ziel betroffen ist, versengen die Flammen in regelmäßigen Abständen auch seine in der Nähe befindlichen Verbündeten und fügen ihnen 250 Schaden zu." }
entries[20020] = { ["name"] = "Stiefel - Große Ausdauer", ["text"] = "Wirken in 5 sek.\nBenötigt Stiefel\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nTraumstaub (10)\nStiefel dauerhaft verzaubern, sodass die Ausdauer um +7 erhöht wird." }
