entries[20022] = { ["name"] = "Seelenstein herstellen", ["text"] = "Sofort\nLässt einen Seelenstein entstehen, der beim Tod verwendet werden kann, um seinen Besitzer wieder mit 400% Gesundheit und Mana ins Leben zu rufen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[20023] = { ["name"] = "Stiefel - Große Beweglichkeit", ["text"] = "Wirken in 5 sek.\nBenötigt Stiefel\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nGroße ewige Essenz (8)\nStiefel dauerhaft verzaubern, sodass die Beweglichkeit um +7 erhöht wird." }
entries[20024] = { ["name"] = "Stiefel - Willenskraft", ["text"] = "Wirken in 5 sek.\nBenötigt Stiefel\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nGroße ewige Essenz (2), Geringe ewige Essenz\nStiefel dauerhaft verzaubern, sodass die Willenskraft um +5 erhöht wird." }
entries[20025] = { ["name"] = "Brust - Große Werte", ["text"] = "Wirken in 5 sek.\nBenötigt Brust, Brust\nTools: Runenverzierte Arkanitrute\nReagenzien:\nGroßer glänzender Splitter (4), Illusionsstaub (15), Große ewige Essenz (10)\nEin Teil der Brustrüstung dauerhaft verzaubern, sodass alle Werte um +4 erhöht werden." }
entries[20026] = { ["name"] = "Brust - Erhebliche Gesundheit", ["text"] = "Wirken in 5 sek.\nBenötigt Brust, Brust\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nIllusionsstaub (6), Kleiner glänzender Splitter\nEin Teil der Brustrüstung dauerhaft verzaubern, sodass die Gesundheit um +100 erhöht wird." }
