entries[20154] = { ["name"] = "Siegel der Rechtschaffenheit", ["text"] = "20 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit heiligem Geist, der jedem Nahkampfangriff zusätzlichen Heiligschaden in Höhe von [1.2 * ( 216 * 1.2 * 1.03 * Haupthandwaffen-Max-Grundgeschwindigkeit / 100) + 0.03 * (Haupthandwaffen-Max-Schaden + Haupthandwaffen-Min-Schaden) / 2 + 1] verleiht. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein." }
entries[20162] = { ["name"] = "Siegel des Kreuzfahrers", ["text"] = "40 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit dem Geist eines Kreuzfahrers und verleiht 68 Nahkampfangriffskraft. Außerdem greift der Paladin um 40% schneller an, verursacht jedoch bei jedem Angriff weniger Schaden. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 Sek. lang und erhöht den erlittenen Heiligschaden um bis zu 35. Eure Nahkampfangriffe frischen die Dauer dieses Siegels auf. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[20164] = { ["name"] = "Siegel der Gerechtigkeit", ["text"] = "10% von Grundmana\nSofort\nErfüllt den Paladin 30 Sek. lang mit dem Geist der Gerechtigkeit, der jedem Nahkampfangriff eine Chance verleiht, 2 Sek. lang zu betäuben. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 Sek. lang und hindert ihn an der Flucht. Eure Nahkampfangriffe frischen die Dauer dieses Siegels auf. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[20165] = { ["name"] = "Siegel des Lichts", ["text"] = "110 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit göttlichem Licht, das jedem Nahkampfangriff eine Chance verleiht, den Paladin um 39 zu heilen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 Sek. lang und verleiht Nahkampfangriffen, die gegen den gerichteten Feind ausgeführt werden, eine Chance den Angreifer um 25 zu heilen. Eure Nahkampfangriffe erneuern die Dauer dieses Effekts. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[20166] = { ["name"] = "Siegel der Weisheit", ["text"] = "135 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit göttlicher Weisheit, die jedem Nahkampfangriff eine Chance verleiht, 50 Mana des Paladins wiederherzustellen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 Sek. lang und verleiht Angriffen und Zaubern, die gegen den gerichteten Feind ausgeführt werden, eine Chance beim Angreifer 33 Mana wiederherzustellen. Eure Nahkampfangriffe erneuern die Dauer dieses Effekts. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
