entries[20680] = { ["name"] = "Blizzard", ["text"] = "150 Mana 30 Meter Reichweite\nWirken in 1 sek.\nRuft einen Blizzard herbei, der 10 Sek. lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. 2850 bis 3150 Frostschaden zufügt." }
entries[20681] = { ["name"] = "Wasserelementarer beschwören", ["text"] = "200 Mana\nSofort\nBeschwört 3 mächtige Wasserelementare, die den Zaubernden unterstützen." }
entries[20682] = { ["name"] = "Teleporter", ["text"] = "45 Meter Reichweite\nSofort\nTeleportiert einen Feind über den Hafen von Theramore." }
entries[20683] = { ["name"] = "Gerechtigkeit des Hochlords", ["text"] = "100 Mana\nSofort\nBetäubt in der Nähe befindliche Feinde, sodass sie sich 5 Sek. lang weder bewegen noch angreifen können." }
entries[20684] = { ["name"] = "Spalten", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nFügt einem Feind und seinem nächsten Verbündeten Waffenschaden plus 30 zu, wirkt auf bis zu 4 Ziele." }
entries[20685] = { ["name"] = "Sturmblitz", ["text"] = "40 Meter Reichweite\nWirken in 1 sek.\nWirft einen Hammer gegen einen Feind, verursacht 1425 bis 1575 körperlichen Schaden und betäubt das Ziel 8 Sek. lang." }
entries[20686] = { ["name"] = "Wegschlagen", ["text"] = "10 Meter Reichweite\nSofort\nFügt in der Nähe befindlichen Feinden normalen Schaden plus 30 zu und stößt sie zurück." }
entries[20687] = { ["name"] = "Sternenregen", ["text"] = "500 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nFügt 10 Sek. lang Feinden im ausgewählten Gebiet alle 2 Sek. 950 bis 1050 Arkanschaden zu." }
entries[20688] = { ["name"] = "Sengpfeil", ["text"] = "50 Meter Reichweite\nBenötigt Distanzwaffe\nReagenzien:\nFeuerteer\nSchießt einen Flammenpfeil gegen einen Feind und fügt Waffenschaden plus 600 zu. Jeglicher zugefügte Schaden basiert auf Feuermagie." }
entries[20690] = { ["name"] = "Mondfeuer", ["text"] = "375 Mana 50 Meter Reichweite\nSofort\nFügt einem Feind 1520 bis 1680 Arkanschaden zu und dann 12 Sek. lang alle 3 Sek. zusätzlich 475 bis 525 Schaden." }
entries[20691] = { ["name"] = "Spalten", ["text"] = "15 Meter Reichweite\nNächster Nahkampf\nFügt einem Feind und seinen nächsten Verbündeten normalen Schaden zu. Wirkt auf bis zu 5 Ziele." }
entries[20692] = { ["name"] = "Feuerball", ["text"] = "50 Meter Reichweite\nWirken in 1.5 sek.\nVerursacht 2890 bis 3910 Feuerschaden bei einem Feind." }
entries[20694] = { ["name"] = "Heilige Nova", ["text"] = "315 Mana\nSofort\nVerursacht eine Explosion göttlichen Lichts, fügt in der Nähe befindlichen Feinden 720 bis 880 Heiligschaden zu und verringert bis Abbruch lang des Zaubernden Maß an Bedrohung." }
entries[20695] = { ["name"] = "Heilige Pein", ["text"] = "100 Mana 40 Meter Reichweite\nWirken in 1.5 sek.\nZerschmettert einen Feind und fügt ihm 1350 bis 1650 Heiligschaden zu." }
entries[20696] = { ["name"] = "Heilige Pein", ["text"] = "100 Mana 40 Meter Reichweite\nWirken in 1.5 sek.\nZerschmettert einen Feind und fügt ihm 1350 bis 1650 Heiligschaden zu." }
entries[20697] = { ["name"] = "Machtwort: Schild", ["text"] = "200 Mana 40 Meter Reichweite\nSofort\nUmgibt den Zaubernden mit einem Schild, der bis zu 30 Sek. lang bestehen bleibt und maximal 5000 körperlichen oder magischen Schaden absorbiert. Solange der Schild hält, werden Zauber nicht durch körperliche Angriffe unterbrochen." }
entries[20698] = { ["name"] = "Zorn", ["text"] = "200 Mana 40 Meter Reichweite\nWirken in 1 sek.\nSchleudert einen Blitzschlag auf einen Feind und verursacht 1020 bis 1380 Naturschaden." }
entries[20699] = { ["name"] = "Wucherwurzeln", ["text"] = "30 Meter Reichweite\nSofort\nUmwickelt in der Nähe befindliche Feinde mit Wurzeln, macht sie bis zu 15 Sek. lang bewegungsunfähig und fügt ihnen alle 3 Sek. 333 bis 367 Naturschaden zu." }
entries[20700] = { ["name"] = "Ritual der Verdammnis" }
entries[20701] = { ["name"] = "Verjüngung", ["text"] = "200 Mana 40 Meter Reichweite\nSofort\nHeilt einen Verbündeten 12 Sek. lang alle 3 Sek." }
entries[20702] = { ["name"] = "Treantverbündete beschwören", ["text"] = "Wirken in 1.5 sek.\nBeschwört 2 Treantverbündete als Begleitung für den Zaubernden bis zur Freigabe." }
entries[20705] = { ["name"] = "Machtschild 500", ["text"] = "Falls man im Gefecht Opfer eines kritischen Treffers wird, besteht eine Chance von 1%, in einen magischen Schild gehüllt zu werden, der die nächsten 515 Schaden absorbiert.\n(Procchance: 5%)" }
entries[20706] = { ["name"] = "Machtwort: Schild 500", ["text"] = "40 Meter Reichweite\nSofort\nNutzt die Kraft der Seele zum Abschirmen und absorbiert dabei 515 Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 Sek. lang nicht wieder abgeschirmt werden." }
entries[20707] = { ["name"] = "Seelensteinauferstehung", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nSpeichert die Seele des befreundeten Ziels. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 400 Gesundheit und 700 Mana wiederbelebt werden." }
entries[20708] = { ["name"] = "Emoticon Status Bereit" }
entries[20709] = { ["name"] = "Arkanitdietrich", ["text"] = "5 Meter Reichweite\nWirken in 5 sek.\nErmöglicht das Öffnen von kniffligen Schlössern. Dieser Vorgang verzehrt den Dietrich." }
entries[20710] = { ["name"] = "Innerer Mut 20", ["text"] = "Chance von +10%, Furchtzaubern und Furchteffekten zu widerstehen." }
entries[20711] = { ["name"] = "Geist der Erlösung", ["text"] = "Erhöht die gesamte Willenskraft um 5% und beim Tod verwandelt sich der Priester 15 Sek. lang in einen Geist der Erlösung. Der Geist kann sich weder bewegen oder angreifen, noch kann er das Ziel von Zaubern oder Effekten sein. In dieser Gestalt kann der Priester jeglichen Heilzauber ohne irgendwelche Kosten wirken. Nach Ablauf der Verwandlung stirbt der Priester." }
entries[20712] = { ["name"] = "Flammenatem", ["text"] = "Sofort\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 833 bis 967 Feuerschaden zu." }
entries[20714] = { ["name"] = "Feuerball", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nFügt einem Gegner Feuerschaden zu." }
