entries[20716] = { ["name"] = "Sandatem", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden Arkanschaden zu und verlangsamt ihr Bewegungs- und Angriffstempo 10 Sek. lang." }
entries[20717] = { ["name"] = "Sandatem", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden Arkanschaden zu und verlangsamt ihr Bewegungs- und Angriffstempo 10 Sek. lang." }
