entries[20729] = { ["name"] = "Segen der Opferung", ["text"] = "100 Mana 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nWendet einen Segen auf das Gruppenmitglied an und überträgt 55 des erlittenen Schadens pro Treffer auf den Zaubernden. Hält 30 Sek. lang an. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
