entries[20733] = { ["name"] = "Schwarzer Pfeil", ["text"] = "Wirken in 2 sek.\nVerflucht einen Feind, verursacht 1 Min. lang regelmäßig Schattenschaden. Falls das Ziel stirbt, während es von 'Schwarzer Pfeil' betroffen ist, kommt es zur Beschwörung von 200 Skelette aus dem Leichnam des Ziels." }
entries[20735] = { ["name"] = "Mehrfachschuss", ["text"] = "30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nFeuert eine Salve von Schüssen auf einen Feind und seine nächsten Verbündeten ab, fügt normalen Schaden plus 225 zu, wirkt auf bis zu 10 Ziele." }
