entries[20739] = { ["name"] = "Wiedergeburt", ["text"] = "68% von Grundmana 30 Meter Reichweite\nWirken in 2 sek. 20 min Abklingzeit\nReagenzien:\nSchlingendornsamenkorn\nLässt den Geist in den Körper zurückkehren und bringt ein totes Ziel mit 750 Gesundheit und 1200 Mana wieder ins Leben zurück." }
